// Step 1: Research emotional problems using search data
// Read from webhook body (standard n8n webhook format)
const body = $json.body || $json;
const niche = body.niche || 'parenting';
const keywords = body.keywords || [];

// Output structure for trend research
// Return array format as expected by n8n
return [{
  json: {
    niche: niche,
    keywords: keywords,
    timestamp: new Date().toISOString(),
    step: 'trend_research',
    ready_for_ai: true
  }
}];

// Parse JSON response from Anthropic Messages API.
// Response shape: { content: [{ type: 'text', text: '...' }], ... }
const data = $input.item.json;
let text;
if (Array.isArray(data.content) && data.content.length > 0) {
  text = data.content[0].text;
} else {
  text = data.text || data.response || data.content;
}

if (typeof text !== 'string') {
  throw new Error('Unexpected Claude response shape: ' + JSON.stringify(data).substring(0, 200));
}

// Strip markdown code fences Claude sometimes wraps JSON in.
text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

try {
  return [{ json: JSON.parse(text) }];
} catch (e) {
  throw new Error(`Failed to parse Claude response as JSON: ${e.message}. Response was: ${text.substring(0, 200)}`);
}

// Step 4: Prepare Canva design request
const titleData = $('Step 2b: Parse Title JSON').item.json;
const claudeContent = $input.item.json;
let contentMarkdown;
if (Array.isArray(claudeContent.content) && claudeContent.content.length > 0) {
  contentMarkdown = claudeContent.content[0].text;
} else {
  contentMarkdown = claudeContent.response || claudeContent.text || '';
}

return [{
  json: {
    title: titleData.title,
    subtitle: titleData.subtitle,
    target_audience: titleData.target_audience,
    content_markdown: contentMarkdown,
    canva_request: {
      design_type: { type: 'preset', name: 'presentation' },
      title: titleData.title
    },
    style_meta: {
      pages_needed: 20,
      style: 'professional_warm',
      color_scheme: 'emotional_trustworthy',
      cover_image_source: 'unsplash',
      author_persona: 'experienced_parent',
      template: 'guide-template-emotional'
    },
    next_step: 'shopify_setup'
  }
}];

// Step 6: Prepare YouTube influencer outreach campaign
const shopifyResp = $input.item.json;
const product = (shopifyResp && shopifyResp.product) || {};
const titleData = $('Step 2b: Parse Title JSON').item.json;
const niche = $('Step 1: Identify Problem').item.json.niche;

const shopifyDomain = $env.SHOPIFY_DOMAIN;
let productUrl = 'pending';
if (shopifyDomain && product.handle) {
  productUrl = `https://${shopifyDomain}/products/${product.handle}`;
} else if (product.admin_graphql_api_id) {
  productUrl = product.admin_graphql_api_id;
}

return [{
  json: {
    outreach_campaign: {
      niche: niche,
      product_title: titleData.title,
      product_id: product.id || null,
      product_url: productUrl,
      target_platforms: ['youtube'],
      offer_structure: {
        option_a: {
          type: 'high_commission',
          rate: '50%',
          description: 'Earn 50% commission on every sale'
        },
        option_b: {
          type: 'flat_fee_plus_commission',
          flat_fee: '$700',
          commission: '15%',
          description: '$700 upfront + 15% ongoing commission'
        }
      },
      video_requirements: {
        duration: '30-60 seconds',
        integration_type: 'sponsored_segment',
        talking_points: [
          'Authentic problem-solution story',
          'Personal connection to the struggle',
          'Clear call-to-action with discount code'
        ]
      },
      influencer_criteria: {
        min_subscribers: 10000,
        niche_match: niche,
        engagement_rate: '>3%',
        audience_demographics: 'parents, caregivers'
      }
    },
    status: 'ready_for_outreach',
    next_step: 'send_outreach_emails'
  }
}];
